import numpy as np; W=dict(np.load('weights.npz'))
for n in ['W_v.0','W_fc.0','W_q.0','W_k.0']:
  s=np.linalg.svd(W[n],compute_uv=False)
  print(n,' '.join(f'{i}:{v:.2f}' for i,v in enumerate(s[:90])))
  print('ratios', ' '.join(f'{i}:{s[i]/s[i+1]:.2f}' for i in range(90) if s[i]/s[i+1]>1.06))

